     1→/**
     2→ * Spec Item API Routes
     3→ *
     4→ * REST endpoints for spec item operations:
     5→ * - GET /api/items - list with filters and pagination
     6→ * - GET /api/items/:ref - get single item
     7→ * - GET /api/items/:ref/tasks - get linked tasks
     8→ *
     9→ * AC Coverage:
    10→ * - ac-8: GET /api/items returns array of spec items
    11→ * - ac-9: Type filter with multi-value support
    12→ * - ac-10: GET /api/items/:ref with full details
    13→ * - ac-11: GET /api/items/:ref/tasks via AlignmentIndex
    14→ */
    15→
    16→import { Elysia, t } from 'elysia';
    17→import {
    18→  initContext,
    19→  loadAllItems,
    20→  loadAllTasks,
    21→  ReferenceIndex,
    22→  AlignmentIndex,
    23→  getCachedTestCoverage,
    24→  computeACCoverage,
    25→  type LoadedSpecItem,
    26→} from '../../parser/index.js';
    27→
    28→interface ItemsRouteOptions {}
    29→
    30→/**
    31→ * Compute parent ULIDs for items based on _path and _sourceFile.
    32→ * Items are nested when they share the same source file and
    33→ * one item's path is a prefix of another's path.
    34→ */
    35→function computeParentMap(items: LoadedSpecItem[]): Map<string, string | undefined> {
    36→  const parentMap = new Map<string, string | undefined>();
    37→
    38→  // Group items by source file
    39→  const byFile = new Map<string, LoadedSpecItem[]>();
    40→  for (const item of items) {
    41→    const file = item._sourceFile || '';
    42→    if (!byFile.has(file)) {
    43→      byFile.set(file, []);
    44→    }
    45→    byFile.get(file)!.push(item);
    46→  }
    47→
    48→  // For each file, determine parent relationships based on path
    49→  for (const [, fileItems] of byFile) {
    50→    // Sort by path length (shorter paths are potential parents)
    51→    const sorted = [...fileItems].sort((a, b) => {
    52→      const aLen = a._path?.length || 0;
    53→      const bLen = b._path?.length || 0;
    54→      return aLen - bLen;
    55→    });
    56→
    57→    for (const item of sorted) {
    58→      const itemPath = item._path;
    59→
    60→      if (!itemPath) {
    61→        // Root item in file - no parent
    62→        parentMap.set(item._ulid, undefined);
    63→        continue;
    64→      }
    65→
    66→      // Find the closest parent by matching path prefix
    67→      // Path format: "features[0].requirements[0]"
    68→      // Parent path: "features[0]" or undefined (root item)
    69→      const lastDot = itemPath.lastIndexOf('.');
    70→      const parentPath = lastDot > -1 ? itemPath.substring(0, lastDot) : undefined;
    71→
    72→      // Find parent item
    73→      let parentUlid: string | undefined;
    74→      if (parentPath === undefined) {
    75→        // Direct child of the root item (the item with no path)
    76→        const rootItem = fileItems.find(i => !i._path);
    77→        parentUlid = rootItem?._ulid;
    78→      } else {
    79→        // Find item with matching parent path
    80→        const parentItem = fileItems.find(i => i._path === parentPath);
    81→        parentUlid = parentItem?._ulid;
    82→      }
    83→
    84→      parentMap.set(item._ulid, parentUlid);
    85→    }
    86→  }
    87→
    88→  return parentMap;
    89→}
    90→
    91→export function createItemsRoutes(options: ItemsRouteOptions = {}) {
    92→  // No closure-scoped kspecDir needed - comes from middleware
    93→
    94→  return new Elysia({ prefix: '/api/items' })
    95→    // AC: @api-contract ac-8, ac-9 - List items with type filter
    96→    .get(
