   102→
   103→        // Compute parent relationships from path structure
   104→        const parentMap = computeParentMap(items);
   105→
   106→        // Apply filters
   107→        let filtered = items;
   108→
   109→        // AC: @api-contract ac-9 - Multi-value type filter
   110→        if (query.type) {
   111→          const typeFilters = Array.isArray(query.type) ? query.type : [query.type];
   112→          filtered = filtered.filter((item) => typeFilters.includes(item.type));
   113→        }
   114→
   115→        // Optional maturity filter (not in ACs but useful)
   116→        if (query.maturity) {
   117→          const maturityFilters = Array.isArray(query.maturity) ? query.maturity : [query.maturity];
   118→          filtered = filtered.filter((item) => {
   119→            if (typeof item.status === 'object' && item.status?.maturity) {
   120→              return maturityFilters.includes(item.status.maturity);
   121→            }
   122→            return false;
   123→          });
   124→        }
