   179→          implementation: t.Optional(t.Union([t.String(), t.Array(t.String())])),
   180→          tag: t.Optional(t.Union([t.String(), t.Array(t.String())])),
   181→          limit: t.Optional(t.String()),
   182→          offset: t.Optional(t.String()),
   183→        }),
   184→      }
   185→    )
   186→
   187→    // AC: @api-contract ac-10 - Get single item by ref
   188→    .get(
   189→      '/:ref',
   190→      async ({ params, error: errorResponse, projectContext }) => {
   191→        // AC: @multi-directory-daemon ac-1, ac-24 - Use project context from middleware
   192→        const ctx = await initContext(projectContext.path);
   193→        const items = await loadAllItems(ctx);
   194→        const tasks = await loadAllTasks(ctx);
   195→        const index = new ReferenceIndex(tasks, items);
   196→
   197→        // Compute parent relationships from path structure
   198→        const parentMap = computeParentMap(items);
   199→
   200→        // AC: @api-contract ac-10, @trait-api-endpoint ac-2 - Resolve ref via ReferenceIndex
   201→        const result = index.resolve(params.ref);
   202→
   203→        if (!result.ok) {
