   207→            message: `Item reference "${params.ref}" not found`,
   208→            suggestion: 'Use kspec item list or kspec search to find valid item references',
   209→          });
   210→        }
   211→
   212→        // Find the item
   213→        const item = items.find((i) => i._ulid === result.ulid);
   214→        if (!item) {
   215→          return errorResponse(404, {
